import{_ as o,o as a,c as t,a5 as n}from"./chunks/framework.DJo0M80U.js";const _=JSON.parse('{"title":"JavaScript 构造函数的特点","description":"JavaScript 构造函数是用于创建和初始化对象的特殊函数。构造函数的主要特点如下： 1. 使用 new 关键字调用 构造函数通常与 new 关键字一起使用。当使用 new 调用构造函数时，会执行以下操作： 创建一个新的空对象。 将这个空对象的 proto 属性指向构造函数的。","frontmatter":{"title":"JavaScript 构造函数的特点","date":"2026-08-11T00:00:00.000Z","categories":["JavaScript 系统教程"],"tags":["JavaScript","前端","教程","OneNote","对象、数组与函数"],"description":"JavaScript 构造函数是用于创建和初始化对象的特殊函数。构造函数的主要特点如下： 1. 使用 new 关键字调用 构造函数通常与 new 关键字一起使用。当使用 new 调用构造函数时，会执行以下操作： 创建一个新的空对象。 将这个空对象的 proto 属性指向构造函数的。","sidebarWeight":26,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/b-原生js/引用数据类型-函数/JavaScript 构造函数的特点.md"},"headers":[],"relativePath":"posts/JavaScript系统教程/03-对象、数组与函数/JavaScript 构造函数的特点.md","filePath":"posts/JavaScript系统教程/03-对象、数组与函数/JavaScript 构造函数的特点.md"}'),i={name:"posts/JavaScript系统教程/03-对象、数组与函数/JavaScript 构造函数的特点.md"};function l(s,e,c,r,p,d){return a(),t("div",null,[...e[0]||(e[0]=[n('<div><h1 id="javascript-构造函数的特点" tabindex="-1">JavaScript 构造函数的特点 <a class="header-anchor" href="#javascript-构造函数的特点" aria-label="Permalink to &quot;JavaScript 构造函数的特点&quot;">​</a></h1><blockquote><p>本节目标：理解“JavaScript 构造函数的特点”的核心思路，并能把它用于实际开发或面试表达。 JavaScript 构造函数是用于创建和初始化对象的特殊函数。构造函数的主要特点如下：</p></blockquote><ol><li>使用 <code>new</code> 关键字调用 构造函数通常与 <code>new</code> 关键字一起使用。当使用 <code>new</code> 调用构造函数时，会执行以下操作：</li></ol><ul><li>创建一个新的空对象。</li><li>将这个空对象的 <code>__proto__</code> 属性指向构造函数的 <code>prototype</code> 属性。</li><li>将构造函数中的 <code>this</code> 绑定到这个新对象。</li><li>执行构造函数中的代码。</li><li>如果构造函数返回非对象，则自动返回这个新对象。 function Person(name, age) { this.name = name; this.age = age; } let person1 = new Person(&#39;Alice&#39;, 25); console.log(person1); // 输出: Person { name: &#39;Alice&#39;, age: 25 }</li></ul><ol start="2"><li><p>使用 <code>this</code> 关键字 在构造函数中，<code>this</code> 关键字指向新创建的对象。通过 <code>this</code> 可以给新对象添加属性和方法。 function Person(name, age) { this.name = name; this.age = age; this.sayHello = function() { console.log(&#39;Hello, my name is &#39; + this.name); }; } let person2 = new Person(&#39;Bob&#39;, 30); person2.sayHello(); // 输出: Hello, my name is Bob</p></li><li><p>构造函数的原型属性 每个构造函数都有一个 <code>prototype</code> 属性，这个属性是一个对象，包含构造函数所创建的所有实例共享的方法和属性。通过修改 <code>prototype</code> 属性，可以为所有实例添加方法和属性。 function Person(name, age) { this.name = name; this.age = age; } Person.prototype.sayHello = function() { console.log(&#39;Hello, my name is &#39; + this.name); }; let person3 = new Person(&#39;Charlie&#39;, 35); person3.sayHello(); // 输出: Hello, my name is Charlie</p></li><li><p>返回值 如果构造函数显式返回一个对象，则返回该对象；如果返回的是基本类型（如字符串、数字等）或没有返回值，则返回新创建的对象。 function Person(name, age) { this.name = name; this.age = age; return { name: &#39;Override&#39;, age: 99 }; // 显式返回一个对象 } let person4 = new Person(&#39;Dave&#39;, 40); console.log(person4); // 输出: { name: &#39;Override&#39;, age: 99 } function Animal(type) { this.type = type; return 123; // 返回一个基本类型 } let animal = new Animal(&#39;Dog&#39;); console.log(animal); // 输出: Animal { type: &#39;Dog&#39; }</p></li><li><p>使用 <code>instanceof</code> 运算符 通过 <code>instanceof</code> 运算符可以检测一个对象是否是某个构造函数的实例。这是通过检查对象的原型链实现的。 function Person(name, age) { this.name = name; this.age = age; } let person5 = new Person(&#39;Eve&#39;, 28); console.log(person5 instanceof Person); // 输出: true console.log(person5 instanceof Object); // 输出: true</p></li></ol><p>总结 JavaScript 构造函数具有以下特点：</p><ul><li>使用 <code>new</code> 关键字调用。</li><li>使用 <code>this</code> 关键字绑定新创建的对象。</li><li>每个构造函数都有一个 <code>prototype</code> 属性，包含共享的方法和属性。</li><li>构造函数可以显式返回一个对象，如果返回的是基本类型或没有返回值，则返回新创建的对象。</li><li>通过 <code>instanceof</code> 运算符可以检测对象是否是某个构造函数的实例。 了解这些特点有助于更好地理解和使用 JavaScript 的面向对象编程。</li></ul></div>',1)])])}const g=o(i,[["render",l]]);export{_ as __pageData,g as default};
